INSERT INTO site_settings (key, value) VALUES ('about_bio_p1', 'Lt Col (Dr) Rahul Sandhu is a dedicated and highly skilled Surgical Oncologist with over 15 years of experience in clinical surgery, emergency trauma care, and military medicine. He completed his specialized Fellowship in Surgical Oncology at the prestigious Homi Bhabha Cancer Hospital and Research Centre (HBCHRC), Punjab (Tata Memorial Centre).') ON CONFLICT DO NOTHING;
INSERT INTO site_settings (key, value) VALUES ('about_bio_p2', 'Prior to his full-time cancer practice, Dr. Sandhu served with distinction as a Graded Surgical Specialist in the Indian Armed Forces (2010–2024). He led the Department of General Surgery and Emergency Trauma Care at Military Hospital, Panagarh—one of the busiest zonal military hospitals under Eastern Command. His distinguished military tenures span high-stress operational deployments including the Siachen Glacier and international combined surgical exercises like the Indo-French Joint Exercise in 2015.') ON CONFLICT DO NOTHING;
INSERT INTO site_settings (key, value) VALUES ('about_bio_p3', 'Dr. Sandhu specializes in breast oncoplastic surgery, gastrointestinal and colorectal malignancies, head & neck resections, gynaecological oncology, and advanced minimally invasive laparoscopic procedures. His practice philosophy centers on compassionate communication, evidence-based multidisciplinary care, and surgical excellence.') ON CONFLICT DO NOTHING;
