INSERT INTO specialties (id, slug, title, subtitle, excerpt, description, symptoms, diagnosis, surgical_approaches, post_care, image, order_num, is_published, created_at, updated_at) VALUES ('spec-1', 'breast-cancer', 'Breast Cancer', 'Breast-Conserving Surgery & Oncoplastic Resection', 'Comprehensive surgical treatment for breast carcinomas, including lumpectomy, sentinel node biopsy, and oncoplastic reconstruction designed for complete clearance and natural aesthetics.', 'Breast cancer surgical care requires a balance of absolute oncological clearance and cosmetic preservation. Dr. Rahul Sandhu provides advanced breast-conserving surgery (BCS), sentinel lymph node biopsy (SLNB) to spare healthy axillary nodes, and oncoplastic breast reconstruction.', 'Painless lump in the breast or armpit, skin dimpling or puckering, nipple inversion or discharge, redness or thickening of breast skin.', 'Triple assessment: Clinical breast examination, bilateral digital mammography / ultrasound breast, and Core needle biopsy under image guidance.', 'Breast-conserving lumpectomy, Modified Radical Mastectomy (MRM), Sentinel Lymph Node Biopsy with radio-tracer/dye, Oncoplastic flap reconstruction.', 'Postoperative drain care instructions, early arm mobility exercises, lymphedema prevention guidance, and seamless handoff to multidisciplinary tumor board for systemic therapy.', '/images/specialties/breast-cancer.jpg', 1, 1, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO specialties (id, slug, title, subtitle, excerpt, description, symptoms, diagnosis, surgical_approaches, post_care, image, order_num, is_published, created_at, updated_at) VALUES ('spec-2', 'colorectal-cancer', 'Colorectal Cancer', 'Minimally Invasive Colon & Rectal Resection', 'State-of-the-art laparoscopic and open surgeries for colon and rectal malignancies, focused on sphincter preservation, low complications, and rapid postoperative recovery.', 'Colorectal tumors require precise anatomical resection along embryological planes (Complete Mesocolic Excision / Total Mesorectal Excision) to ensure adequate lymph node yield while safeguarding pelvic nerves and sphincter function.', 'Unexplained alteration in bowel habits (chronic diarrhea or constipation), rectal bleeding or dark stools, persistent abdominal cramps or bloating, unexplained weight loss and fatigue.', 'High-definition Colonoscopy with tissue biopsy, Contrast-Enhanced CT Abdomen-Pelvis, MRI Pelvis for rectal tumors, and serum CEA monitoring.', 'Laparoscopic Right/Left Hemicolectomy, Anterior Resection, Low Anterior Resection (LAR) with sphincter preservation, Abdominoperineal Resection (APR) when indicated.', 'Enhanced Recovery After Surgery (ERAS) protocol, early oral refeeding, stoma education and nursing support where temporary diversion is created.', '/images/specialties/colorectal-cancer.jpg', 2, 1, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO specialties (id, slug, title, subtitle, excerpt, description, symptoms, diagnosis, surgical_approaches, post_care, image, order_num, is_published, created_at, updated_at) VALUES ('spec-3', 'head-neck-cancer', 'Head & Neck Cancer', 'Oral Cavity, Larynx & Neck Dissections', 'Advanced oncologic resections for oral cavity, tongue, buccal mucosa, salivary gland, and throat cancers with functional microvascular reconstructive alignment.', 'Head and neck oncologic surgery demands meticulous margin clearance coupled with careful preservation of facial aesthetics, speech, swallowing, and airway patency. Dr. Rahul Sandhu brings deep military surgical discipline and oncological fellowship training to these complex cases.', 'Non-healing mouth ulcers lasting over two weeks, persistent sore throat or difficulty swallowing, red or white patches inside the mouth, unilateral neck swelling or lump.', 'Detailed clinical endoscopy, biopsy of the primary oral lesion, Contrast CT or MRI of head and neck, and Fine Needle Aspiration (FNAC) of cervical lymph nodes.', 'Composite resection, wide local excision of tongue/buccal mucosa with margin control, Selective and Modified Radical Neck Dissection, reconstructive local and regional flaps.', 'Airway monitoring, specialized nutritional support, speech and swallowing rehabilitation, oral hygiene management.', '/images/specialties/head-neck-cancer.jpg', 3, 1, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO specialties (id, slug, title, subtitle, excerpt, description, symptoms, diagnosis, surgical_approaches, post_care, image, order_num, is_published, created_at, updated_at) VALUES ('spec-4', 'liver-pancreatic-tumors', 'Liver & Pancreatic Tumors', 'Complex Hepato-Pancreato-Biliary (HPB) Surgery', 'Surgical management of liver masses, bile duct tumors, and pancreatic neoplasms with precision vascular control and multidisciplinary tumor board coordination.', 'Tumors of the liver, gallbladder, bile ducts, and pancreas are among the most surgically demanding. Dr. Rahul Sandhu provides thorough preoperative staging, accurate margin planning, and personalized palliative or curative surgical resections.', 'Painless progressive jaundice (yellowing of eyes and skin), dark urine and pale stools, upper abdominal pain radiating to the back, unexplained appetite loss and weight loss.', 'Triple-phase CT Abdomen, MRCP (Magnetic Resonance Cholangiopancreatography), Endoscopic Ultrasound (EUS) with biopsy, CA 19-9 and AFP tumor markers.', 'Pancreaticoduodenectomy (Whipple Procedure), Distal Pancreatectomy with splenectomy, Non-anatomical and anatomical liver resections, Radical Cholecystectomy.', 'Intensive care monitoring during initial 24-48 hours, enzyme supplementation guidance, strict glucose management, and tailored nutritional recovery.', '/images/specialties/liver-pancreatic-tumors.jpg', 4, 1, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO specialties (id, slug, title, subtitle, excerpt, description, symptoms, diagnosis, surgical_approaches, post_care, image, order_num, is_published, created_at, updated_at) VALUES ('spec-5', 'stomach-cancer', 'Stomach Cancer', 'Gastrectomy & D2 Lymphadenectomy', 'Radical subtotal and total gastrectomy with standardized D2 lymph node clearance for gastric carcinomas and gastrointestinal stromal tumors (GIST).', 'Effective surgical care for stomach cancer centers on achieving microscopic negative margins (R0 resection) along with standardized D2 lymphadenectomy to accurately stage the disease and decrease recurrence rates.', 'Persistent indigestion, burning or epigastric discomfort, early satiety after small meals, nausea or vomiting, iron deficiency anemia or black tarry stools.', 'Upper Gastrointestinal Endoscopy with multiple biopsies, Contrast CT Thorax-Abdomen-Pelvis for staging, and Endoscopic Ultrasound.', 'Subtotal Gastrectomy with Roux-en-Y gastrojejunostomy, Total Gastrectomy with Roux-en-Y esophagojejunostomy, D2 lymph node dissection.', 'Stepwise dietary progression from liquids to small frequent soft meals, vitamin B12 supplementation protocol, and post-gastrectomy dietary counseling.', '/images/specialties/stomach-cancer.jpg', 5, 1, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO specialties (id, slug, title, subtitle, excerpt, description, symptoms, diagnosis, surgical_approaches, post_care, image, order_num, is_published, created_at, updated_at) VALUES ('spec-6', 'thyroid-parathyroid-tumors', 'Thyroid & Parathyroid Tumors', 'Endocrine Surgery with Recurrent Laryngeal Nerve Monitoring', 'Meticulous thyroidectomy and parathyroidectomy preserving the recurrent laryngeal vocal nerves and parathyroid glands while removing malignant endocrine nodules.', 'Surgical removal of thyroid and parathyroid lesions requires microscopic dissection along the trachea to preserve vocal cord nerve function and avoid hypocalcemia, while ensuring complete eradication of primary tumor and central neck nodes.', 'A palpable nodule or swelling in the lower front of the neck, hoarseness of voice, difficulty swallowing or feeling of fullness in the throat, swollen neck nodes.', 'High-resolution neck ultrasound with TI-RADS scoring, Ultrasound-guided FNAC (Bethesda classification), Serum TSH, Free T3/T4, Calcium, and PTH levels.', 'Hemithyroidectomy, Total Thyroidectomy with central compartment neck dissection, Selective lateral neck dissection for nodal metastasis, Minimally invasive parathyroidectomy.', 'Serum calcium monitoring, vocal cord mobility assessment, thyroid hormone replacement calibration, and radioactive iodine (RAI) therapy coordination when indicated.', '/images/specialties/thyroid-parathyroid-tumors.jpg', 6, 1, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO treatments (id, slug, title, subtitle, excerpt, description, indications, procedure_steps, benefits, recovery_info, image, order_num, is_published, created_at, updated_at) VALUES ('treat-1', 'tumor-resection', 'Tumor Resection', 'Precision Oncologic Excision with Margin Clearance', 'Removal of cancerous or complex benign tumors with surgical precision, aiming for complete R0 cancer clearance while preserving surrounding healthy tissue and critical organ function.', 'Tumor Resection Surgery is a cornerstone procedure used to remove cancerous or benign tumors from the body. Performed with meticulous technique, the surgery focuses on complete microscopic margin clearance (R0) while safeguarding neighboring nerves, blood vessels, and healthy anatomy.', 'Primary solid tumors of the breast, gastrointestinal tract, soft tissues, head & neck, and pelvic organs where localized resection provides curative or significant disease-control intent.', 'Preoperative anatomical staging via high-resolution cross-sectional imaging; Careful intraoperative dissection along tissue planes; Frozen section margin evaluation when needed; Hemostasis and functional anatomical reconstruction.', 'High rate of complete cancer clearance, reduction of local recurrence risk, preservation of critical bodily functions, and tissue preservation.', 'Varies from 2 to 5 days in hospital depending on organ site, with structured ambulation, pain management, and wound healing protocols.', '/images/tumor-resection.jpg', 1, 1, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO treatments (id, slug, title, subtitle, excerpt, description, indications, procedure_steps, benefits, recovery_info, image, order_num, is_published, created_at, updated_at) VALUES ('treat-2', 'biopsy-cancer-diagnosis', 'Biopsy & Cancer Diagnosis', 'Accurate Histopathological Sampling for Timely Treatment', 'Crucial diagnostic procedure used to determine whether a suspicious growth or lump is malignant, establishing the exact histological subtype and molecular markers to guide targeted care.', 'Accurate biopsy and cancer diagnosis help detect cancer early, guiding timely and effective treatment decisions. Dr. Sandhu employs image-guided core needle biopsies, incisional biopsies, and excisional biopsies tailored to tumor depth and location.', 'Suspicious breast lumps, enlarged lymph nodes of unknown etiology, soft tissue masses, thyroid nodules, or unexplained abdominal lesions.', 'Evaluation of prior ultrasound or CT scans; Local anesthesia or mild sedation; Precise needle placement or small incision to acquire intact tissue cylinders; Rapid dispatch for histopathology and immunohistochemistry (IHC).', 'Definitive microscopic confirmation, genetic and receptor analysis (HER2, ER/PR, MSI, PD-L1), avoiding unnecessary radical surgeries.', 'Most biopsies are performed as day-care or outpatient procedures with immediate return to light daily activities within 24 hours.', '/images/Cancer-Diagnostic.jpg', 2, 1, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO treatments (id, slug, title, subtitle, excerpt, description, indications, procedure_steps, benefits, recovery_info, image, order_num, is_published, created_at, updated_at) VALUES ('treat-3', 'lymph-node-dissection', 'Lymph Node Dissection', 'Vital Step in Cancer Staging & Regional Control', 'Assessment and removal of regional lymph node basins to determine cancer spread, prevent regional metastasis, and formulate exact adjuvant therapy regimens.', 'Lymph node dissection, also known as lymphadenectomy, is a crucial surgical procedure in cancer care. It involves the targeted removal of one or more groups of lymph nodes to evaluate tumor spread, commonly performed in breast, GI, melanoma, and gynaecological cancers.', 'Confirmed nodal metastasis or high-risk primary solid malignancies (axillary nodes in breast cancer, cervical nodes in head & neck cancer, mesenteric nodes in colorectal cancer).', 'Identification of lymphatic drainage basin; Sentinel node mapping when indicated; Careful dissection preserving major neurovascular bundles; Complete en-bloc removal of regional nodes.', 'Accurate pathological staging (N status), regional disease eradication, prevention of lymph node recurrence, guides chemotherapy and radiation necessity.', 'Surgical drains are maintained for a few days to prevent seroma formation; gentle mobility guidance is provided to prevent lymphedema.', '/images/Lymp-node-disection.jpg', 3, 1, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO treatments (id, slug, title, subtitle, excerpt, description, indications, procedure_steps, benefits, recovery_info, image, order_num, is_published, created_at, updated_at) VALUES ('treat-4', 'minimally-invasive-surgery', 'Minimally Invasive Surgery', 'Laparoscopic Oncology with Smaller Incisions & Faster Recovery', 'Advanced surgical techniques utilizing high-definition cameras and specialized instruments through tiny keyhole incisions, resulting in less pain, reduced blood loss, and rapid healing.', 'Minimally Invasive Surgery (MIS) is a modern surgical approach that uses small incisions and high-definition laparoscopic visualization to achieve identical oncological radicality as open surgery with significantly lower patient trauma.', 'Early to intermediate colon and rectal cancers, gastric lesions, staging laparoscopy, select pelvic tumors, and diagnostic oncology interventions.', 'Insufflation of peritoneal cavity; Placement of 5mm to 10mm trocars; High-magnification 4K endoscopic dissection; Specimen retrieval through protected small incision.', 'Minimal surgical scarring, drastically reduced post-op pain, lower wound infection rates, faster resumption of normal diet and return to family life.', 'Patients frequently ambulate within 12-24 hours and are discharged in 2 to 3 days, resuming everyday routines much faster than traditional open laparotomy.', '/images/Minimal-Invassive-Surgery.jpg', 4, 1, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO treatments (id, slug, title, subtitle, excerpt, description, indications, procedure_steps, benefits, recovery_info, image, order_num, is_published, created_at, updated_at) VALUES ('treat-5', 'reconstructive-surgery', 'Reconstructive Surgery', 'Restoring Form, Function & Quality of Life', 'Specialized surgical care aimed at repairing, restoring, and rebuilding tissue defects following major tumor removal, trauma, or oncological ablation.', 'Reconstructive surgery is an integral branch of cancer care aimed at restoring the form and functional integrity of the body after aggressive cancer removal. Dr. Sandhu integrates reconstructive techniques directly into surgical planning.', 'Extensive tissue resection in breast cancer, head and neck oncological defects, complex abdominal wall reconstruction, and soft tissue defect closures.', 'Pre-excision planning of reconstructive margins; Mobilization of local or regional tissue flaps; Tension-free layered anatomical closure with cosmetic suturing.', 'Restoration of appearance, preservation of bodily function (speech, swallowing, limb movement, body contours), and psychological well-being.', 'Careful monitoring of flap vascularity and wound healing with gradual rehabilitation exercises under medical supervision.', '/images/Reconstructive-Surgery.jpg', 5, 1, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO treatments (id, slug, title, subtitle, excerpt, description, indications, procedure_steps, benefits, recovery_info, image, order_num, is_published, created_at, updated_at) VALUES ('treat-6', 'palliative-surgical-care', 'Palliative Surgical Care', 'Enhancing Comfort, Relieving Pain & Restoring Dignity', 'Compassionate, purpose-driven surgical interventions focused on relieving distressing symptoms, managing bowel obstructions, controlling bleeding, and improving quality of life in advanced stages.', 'Palliative surgery focuses on improving the quality of life for patients with advanced or metastatic cancers. The goal is not curative tumor clearance, but relieving acute distress, easing pain, and restoring physical comfort.', 'Intestinal obstruction, intractable tumor bleeding, debilitating fluid buildup (malignant ascites or pleural effusion), severe pain, or ulcerating tumors.', 'Goal-concordant discussion with patient and family; Minimally invasive bypass, stoma creation, decompression, or palliative tumor de-bulking; Immediate symptom relief focus.', 'Quick relief from distressing nausea, vomiting, or pain; Restoration of enteral nutrition; Improved quality of remaining life and dignity.', 'Rapid mobilization with close palliative care team coordination and focus on home comfort.', '/images/paliative-surgery-care1.jpg', 6, 1, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO treatments (id, slug, title, subtitle, excerpt, description, indications, procedure_steps, benefits, recovery_info, image, order_num, is_published, created_at, updated_at) VALUES ('treat-7', 'gynaecological-cancer-surgery', 'Gynaecological Cancer Surgery', 'Expert Surgical Care for Ovarian, Uterine & Cervical Malignancies', 'Comprehensive open and laparoscopic surgical solutions for reproductive organ tumors, including cytoreductive staging, radical hysterectomy, and fertility-sparing considerations.', 'Gynaecological oncology surgeries address tumors affecting the female reproductive system: ovaries, uterus, cervix, and fallopian tubes. Dr. Rahul Sandhu provides personalized care combining radical oncological clearance with empathetic patient support.', 'Endometrial carcinoma, ovarian malignancies, cervical cancer, complex adnexal masses.', 'Systematic pelvic and abdominal staging; Radical hysterectomy with bilateral salpingo-oophorectomy; Pelvic and para-aortic lymphadenectomy; Optimal debulking in ovarian cases.', 'Thorough removal of pelvic disease, accurate staging, symptom resolution, improved long-term disease control.', 'Patients receive tailored pelvic floor guidance, thrombosis prophylaxis, and supportive recovery protocols over 3-7 days in hospital.', '/images/Gynaecological-cancer.jpg', 7, 1, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO treatments (id, slug, title, subtitle, excerpt, description, indications, procedure_steps, benefits, recovery_info, image, order_num, is_published, created_at, updated_at) VALUES ('treat-8', 'urological-cancer-surgery', 'Urological Cancer Surgery', 'Advanced Interventions for Kidney, Bladder, Prostate & Testicular Tumors', 'Comprehensive diagnosis and specialized surgical treatment for genitourinary cancers utilizing nephron-sparing partial nephrectomy, radical cystectomy, and pelvic lymphadenectomy.', 'Urological oncology involves delicate procedures requiring preservation of renal function, urinary continence, and nerve pathways. Dr. Rahul Sandhu brings proven surgical dexterity to complex renal and pelvic tumors.', 'Renal cell carcinoma (kidney tumors), bladder urothelial cancer, prostate tumors, and testicular neoplasms.', 'Preoperative 3D vascular reconstruction review; Partial or radical nephrectomy; Transurethral resection or radical cystectomy with urinary diversion; Retroperitoneal lymph node dissection.', 'Maximal preservation of functioning kidney tissue where feasible, oncologically sound margin clearance, reduced risk of urinary complications.', 'Close monitoring of renal output, fluid balance, catheter management, and structured home care transition.', '/images/Urological-Cancers.jpg', 8, 1, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO blogs (id, slug, title, excerpt, content, cover_image, category, author, read_time, published_date, is_published, meta_title, meta_description, updated_at, created_at) VALUES ('blog-1', 'cancer-surgery-what-to-expect-before-during-and-after', 'Cancer Surgery: What to Expect Before, During, and After', 'A comprehensive guide by Lt Col (Dr) Rahul Sandhu on navigating cancer surgery—from diagnostic preparation and pre-anesthesia checks to the operating room and supportive post-op recovery.', 'Cancer surgery is a vital part of treatment for many types of cancer. For patients and their families, the word "surgery" often brings a mix of hope, anxiety, and questions. Knowing what to expect at each stage can demystify the process and help you approach your surgery with confidence.
INSERT INTO blogs (id, slug, title, excerpt, content, cover_image, category, author, read_time, published_date, is_published, meta_title, meta_description, updated_at, created_at) VALUES ('blog-2', 'common-fears-before-surgery-and-how-we-help-you-overcome-them', 'Common Fears Before Surgery — And How We Help You Overcome Them', 'Facing surgery for cancer can feel daunting. Dr. Rahul Sandhu addresses common fears around pain, anesthesia, recovery time, and recurrence, replacing anxiety with clarity and hope.', 'Facing surgery—especially for something as serious as cancer—can be one of the most stressful times in a person''s life. Even with the best surgical oncologist and advanced medical technology, anxiety, uncertainty, and fear are entirely natural emotions.
INSERT INTO blogs (id, slug, title, excerpt, content, cover_image, category, author, read_time, published_date, is_published, meta_title, meta_description, updated_at, created_at) VALUES ('blog-3', 'minimally-invasive-cancer-surgery-benefits-and-techniques', 'Minimally Invasive Cancer Surgery: Benefits and Techniques', 'Exploring how laparoscopic and keyhole surgical oncology techniques achieve oncological precision while minimizing trauma, hospital stays, and scarring for patients.', 'Over the past two decades, surgical oncology has undergone a quiet revolution. Where massive abdominal incisions were once obligatory for cancer removal, minimally invasive surgery (MIS) now allows skilled surgeons to achieve identical or superior oncological clearance through small, precise keyhole incisions.
INSERT INTO testimonials (id, author_name, author_location, condition, content, rating, source, is_featured, is_approved, created_at, consent_given, image, order_num) VALUES ('test-1', 'Tavleen Kaur', 'Chandigarh', 'Secondary Oncology Care & Guidance', 'I was referred to Dr. Rahul Sandhu by a close friend when my mother''s condition worsened after receiving cancer treatment at TMC. From the very first meeting, Dr. Sandhu''s positivity and compassion gave us a sense of hope that we had been desperately looking for. He is not just a highly skilled Surgical Oncologist and Lieutenant Colonel, but also an incredibly down-to-earth, gentle, and sophisticated human being. What truly sets him apart is the time he gives to his patients. He explained every step of the treatment clearly, answered all our questions with patience, and made sure we never felt rushed or ignored. In moments of confusion and fear, he became a beacon of clarity and reassurance.', 5, 'Google Reviews (Verified)', 1, 1, '2025-08-14', 1, '', 0) ON CONFLICT DO NOTHING;
INSERT INTO testimonials (id, author_name, author_location, condition, content, rating, source, is_featured, is_approved, created_at, consent_given, image, order_num) VALUES ('test-2', 'Munish Rana', 'Kharar, Punjab', 'Gallbladder & Complex Onco Evaluation', 'My mother was suffering from severe pain and gallbladder swelling. We went to meet Dr Rahul Sandhu an Onco Specialist. From the very first consultation, he made sure to explain the diagnosis clearly and guided us step-by-step through the entire process. Their expertise, compassionate approach, and attention to detail gave us great confidence and hope. Dr Rahul Sandhu always listened very patiently to our concerns and answered all our questions whether in person or over phone calls. The treatment was handled with utmost professionalism. I felt well-supported both medically and emotionally through this tough time.', 5, 'Google Reviews (Verified)', 1, 1, '2025-09-02', 1, '', 0) ON CONFLICT DO NOTHING;
INSERT INTO testimonials (id, author_name, author_location, condition, content, rating, source, is_featured, is_approved, created_at, consent_given, image, order_num) VALUES ('test-3', 'Anchal Pamma', 'Mohali, Punjab', 'Kidney Surgery', 'Would take a moment to appreciate Dr. Sandhu for being an amazing surgeon. We are extremely grateful for the excellent care given to my mother during her kidney surgery. He explained everything clearly, handled the surgery with great expertise, and ensured smooth recovery. Very humble, patient, and approachable. Highly recommended.', 5, 'Google Reviews (Verified)', 1, 1, '2025-07-19', 1, '', 0) ON CONFLICT DO NOTHING;
INSERT INTO testimonials (id, author_name, author_location, condition, content, rating, source, is_featured, is_approved, created_at, consent_given, image, order_num) VALUES ('test-4', 'Sukhmanpreet Kaur', 'Canada (International Patient)', 'Specialized Clinical Care', 'I traveled all the way from Canada to see Dr. Rahul Sandhu, and it was the best decision I could have made. Beyond his medical expertise, he is exceptionally nice, calm, and supportive. He took the time to listen to my concerns and made me feel completely at ease throughout the entire process. If you are looking for effective care from a doctor who truly cares about his patients, go for it. He is one of the best doctors I have ever met. Thank you so much Dr Rahul Sandhu!', 5, 'Google Reviews (Verified)', 1, 1, '2025-06-28', 1, '', 0) ON CONFLICT DO NOTHING;
INSERT INTO testimonials (id, author_name, author_location, condition, content, rating, source, is_featured, is_approved, created_at, consent_given, image, order_num) VALUES ('test-5', 'Devanshi Dhillon', 'Punjab', 'Laparoscopic Surgery', 'I had the first surgery of my life—laparoscopic surgery. I was really scared and anxious about what would happen. But after having an appointment with my surgeon Dr. Rahul Sandhu, he comforted me like a friend. He is empathetic, an active listener, and an excellent communicator who provides thorough explanations and a clear plan of action. Now I am completely fine. It did not even feel like I had surgery. Do consult with him for your health.', 5, 'Google Reviews (Verified)', 1, 1, '2025-05-15', 1, '', 0) ON CONFLICT DO NOTHING;
INSERT INTO testimonials (id, author_name, author_location, condition, content, rating, source, is_featured, is_approved, created_at, consent_given, image, order_num) VALUES ('test-6', 'Satveer Singh', 'Punjab', 'Surgical Care & Recovery', 'I am very satisfied with Dr. Rahul Sandhu''s treatment. He is very nice and polite, and the nursing team is also very efficient. Highly professional doctor who gives true comfort to his patients.', 5, 'Google Reviews (Verified)', 0, 1, '2025-08-01', 1, '', 0) ON CONFLICT DO NOTHING;
INSERT INTO videos (id, title, youtube_url, thumbnail, description, order_num, is_published, created_at) VALUES ('vid-1', 'Understanding Post-Surgical Recovery & Staging', 'https://www.youtube.com/watch?v=dQw4w9WgXcQ', '/images/Cancer-Surgery-Rcovery-300x225.png', 'Lt Col (Dr) Rahul Sandhu discusses what patients and families should expect during hospitalization and postoperative recovery.', 1, 1, '2026-10-22T07:13:17.437Z') ON CONFLICT DO NOTHING;
INSERT INTO videos (id, title, youtube_url, thumbnail, description, order_num, is_published, created_at) VALUES ('vid-2', 'Minimally Invasive Techniques in Modern Cancer Care', 'https://www.youtube.com/watch?v=dQw4w9WgXcQ', '/images/Minimal-Invassive-Surgery.jpg', 'Key advantages of high-definition keyhole techniques, minimal blood loss, and accelerated return to normal daily routines.', 2, 1, '2026-10-22T07:13:17.437Z') ON CONFLICT DO NOTHING;
INSERT INTO faqs (id, question, answer, category, order_num, is_published, created_at) VALUES ('faq-1', 'What is the difference between a General Surgeon and a Surgical Oncologist?', 'A Surgical Oncologist is a specialized surgeon who has completed dedicated sub-specialty fellowship training exclusively in diagnosing, staging, and surgically treating complex benign and malignant tumors. They focus on microscopic margin clearance (R0 resection), systematic lymph node dissection, and multidisciplinary tumor board coordination with medical and radiation oncologists.', 'Clinical Scope', 1, 1, '2026-10-22T07:13:17.436Z') ON CONFLICT DO NOTHING;
INSERT INTO faqs (id, question, answer, category, order_num, is_published, created_at) VALUES ('faq-2', 'Does surgery cause cancer to spread?', 'No, this is an unfounded myth. Surgery does not cause cancer to spread. On the contrary, precise surgical resection is one of the most effective curative modalities for solid organ malignancies when diagnosed in operable stages. Surgical oncologists adhere to strict ''no-touch'' isolation techniques and embryological anatomical dissection planes to eliminate the tumor safely.', 'Safety & Myths', 2, 1, '2026-10-22T07:13:17.436Z') ON CONFLICT DO NOTHING;
INSERT INTO faqs (id, question, answer, category, order_num, is_published, created_at) VALUES ('faq-3', 'Where does Lt Col (Dr) Rahul Sandhu conduct consultations and surgeries?', 'Dr. Rahul Sandhu conducts outpatient consultations and performs oncology surgeries primarily at Shalby Hospital, Mohali (Phase 9, Sector 63). Prior appointment booking is recommended to avoid waiting.', 'Hospital & Locations', 3, 1, '2026-10-22T07:13:17.436Z') ON CONFLICT DO NOTHING;
INSERT INTO faqs (id, question, answer, category, order_num, is_published, created_at) VALUES ('faq-4', 'Can I seek a second opinion on my cancer surgery recommendation?', 'Yes, absolutely. Seeking a second opinion is encouraged in oncological care. Dr. Rahul Sandhu routinely reviews outside pathology slides, cross-sectional imaging (CT/MRI/PET), and treatment plans to provide an independent, evidence-based assessment of surgical feasibility and organ-preservation options.', 'Second Opinions', 4, 1, '2026-10-22T07:13:17.436Z') ON CONFLICT DO NOTHING;
INSERT INTO faqs (id, question, answer, category, order_num, is_published, created_at) VALUES ('faq-5', 'What is Minimally Invasive / Laparoscopic Cancer Surgery?', 'Minimally invasive cancer surgery utilizes 4K high-definition laparoscopes and miniature specialized instruments through tiny incisions (5–10 mm) rather than large abdominal cuts. It results in significantly less postoperative pain, reduced blood loss, shorter hospital stays (2–3 days), and faster recovery.', 'Surgical Technology', 5, 1, '2026-10-22T07:13:17.436Z') ON CONFLICT DO NOTHING;
INSERT INTO faqs (id, question, answer, category, order_num, is_published, created_at) VALUES ('faq-6', 'What should I bring to my initial consultation?', 'Please bring all existing diagnostic reports, including biopsy/histopathology slides and blocks, imaging CDs (CT, MRI, PET, Mammography, Ultrasound), recent blood work, previous discharge summaries, and a complete list of any current daily medications.', 'Consultation Preparation', 6, 1, '2026-10-22T07:13:17.436Z') ON CONFLICT DO NOTHING;
INSERT INTO faqs (id, question, answer, category, order_num, is_published, created_at) VALUES ('faq-7', 'Are cancer surgeries covered under health insurance and cashless empanelment?', 'Yes, Shalby Hospital, Mohali has a dedicated TPA and insurance desk supporting all major private health insurers, corporate TPAs, CGHS, and ECHS panels.', 'Insurance & Billing', 7, 1, '2026-10-22T07:13:17.436Z') ON CONFLICT DO NOTHING;
INSERT INTO faqs (id, question, answer, category, order_num, is_published, created_at) VALUES ('faq-8', 'How soon after surgery can I resume normal daily activities?', 'Under modern Enhanced Recovery After Surgery (ERAS) protocols, patients are encouraged to ambulate and take light fluids within 12 to 24 hours. Full return to light sedentary work typically takes 1 to 2 weeks for keyhole procedures and 3 to 4 weeks for major open abdominal resections.', 'Recovery & ERAS', 8, 1, '2026-10-22T07:13:17.436Z') ON CONFLICT DO NOTHING;
